-- Seed data for amblux_product_pages + amblux_products.page_slug/variant_options/spec.
-- Transcribed from the AMBLUX product spreadsheet's real Marketing Description /
-- features-and-benefits / Application / technical-spec columns, cross-checked
-- against the one page recovered directly from the original site's live DOM
-- (silicone-6x6). Data-quality notes, flagged rather than silently fixed:
--   - Several linear SKUs' IP ratings climbed sequentially across CCT/length
--     variants of the SAME physical product (e.g. IP67/68/69/70) in the raw
--     sheet -- physically implausible for otherwise-identical hardware, so this
--     seed normalizes those to the one IP rating confirmed on the live reference
--     page (IP67) instead of propagating what looks like a data-entry artifact.
--   - rigid-6x8's driver-column wattage reads 7.2 W/m here vs. catalog.ts's
--     configurator constant of 7.5 W/m for the same family -- a real mismatch
--     between the spreadsheet and the ported engine, not reconciled by this
--     migration. Worth a decision on which number is authoritative.
--   - Several 'lm/w' spec values are copied verbatim from the sheet even though
--     lumens-per-watt-vs-per-metre looks like a unit-label typo in the source --
--     preserved as-is rather than guessed at, per this project's own convention.
--   - The surface puck's Chrome SKU (AMB-PK-SLSR35-...-CH) has its Finish column
--     literally reading 'Satin Nickel' in the sheet; the SKU code and catalog.ts
--     both say chrome, so this seed uses 'Chrome' and flags the sheet cell as the
--     likely error, not the SKU.
--   - Six small wire-accessory SKUs mentioned throughout as 'Optional accessories'
--     (AMB-EXT-1M, AMB-Y-EXT, AMB-2M-6PRTDS, AMB-HRW-CBLKT, AMB-FRNT-SWITCH, and
--     AMB-EXT-2M which does already exist) are NOT part of the configurator's
--     real 49-SKU catalog and have no cost/pricing rows -- they're rendered here
--     as inert reference codes only, matching how the original page shows them.
--   - A fourth silicone-10x10-45deg combination (4000K / 5m / 45W) exists in the
--     source sheet but isn't part of catalog.ts's real sold combos -- left out of
--     this seed pending confirmation that AMBLUX actually stocks it.

insert into public.amblux_product_pages (slug, category, eyebrow, name, marketing_paragraphs, features, applications, required_accessories, optional_accessory_codes, variant_axes, linear_family_id, default_sku) values ('silicone-6x6', 'linear', 'Silicone linear', 'Freecut Recess Silicone LED Tape 6 mm x 6 mm', '["Introducing one of the most versatile and innovative flexible linear LED series in the industry, engineered with advanced silicone LED technology to deliver seamless, uniform light diffusion in a sleek, minimalist profile. Designed to create a flawless dotless lighting effect without the bulk of traditional diffusers or lenses, this series combines premium aesthetics with exceptional performance and flexibility.", "Equipped with a high-performance 3M® adhesive backing, installation is fast and effortless in routed grooves or directly onto flat surfaces. Available in multiple lengths and pre-wired with power cables on both ends, the series was developed to simplify installation while offering maximum design freedom.", "Ideal for under-cabinet, closet, furniture, display, and architectural lighting applications, this versatile solution delivers clean lines, elegant ambient illumination, and enhanced functionality in any environment. It is also perfectly suited for vertical installations in closets and pantries, improving visibility and organization while creating a refined, modern lighting experience."]'::jsonb, '["Freecut technology—field-cuttable to any length", "Uniform, dot-free light output", "Recessed installation in a 6 mm x 6 mm routed groove", "High-performance 3M® adhesive backing", "Pre-wired with 1.5m power cables on both ends"]'::jsonb, '["Under-cabinet lighting", "Shelf lighting", "Vertical side-panel lighting", "Toe-kick lighting", "Ambient lighting"]'::jsonb, '[{"title": "1. Compatible 24 V driver", "body": "Select the AMBLUX driver according to the total connected wattage for your run (9 W/m)."}, {"title": "2. Choose one compatible control method", "items": ["AMBLUX dimming control system", "Wired or wireless switch", "Door sensor", "Dimming sensor"]}]'::jsonb, '["AMB-EXT-1M", "AMB-EXT-2M", "AMB-Y-EXT", "AMB-2M-6PRTDS", "AMB-HRW-CBLKT", "AMB-FRNT-SWITCH"]'::jsonb, '[{"key": "length", "label": "Length"}, {"key": "cct", "label": "Colour temperature"}]'::jsonb, 'silicone-6x6', 'AMB-FCST-RC0606-24V-30-24-90-1.5M-13.5W');
insert into public.amblux_product_pages (slug, category, eyebrow, name, marketing_paragraphs, features, applications, required_accessories, optional_accessory_codes, variant_axes, linear_family_id, default_sku) values ('silicone-4x8.5-trim', 'linear', 'Silicone linear', 'Freecut Recess Silicone LED Tape 4 mm x 8.5 mm Translucent Trim', '["Introducing our innovative, flexible linear LED series, engineered with advanced silicone LED technology to deliver smooth, uniform light diffusion in a sleek, minimalist design. Designed to create a flawless dotless lighting effect without the bulk of traditional lenses, this solution combines modern aesthetics with exceptional functionality.", "Equipped with a premium high-bond 3M® adhesive backing, installation is quick and effortless, especially in routed grooves and recessed applications. Available pre-wired with power cables on both ends, this series is specifically designed for vertical installations in closets and pantries, creating elegant ambient illumination while enhancing visibility and organization.", "To ensure a clean, refined finish, the system features a translucent trim that helps conceal minor installation imperfections while maintaining a sophisticated architectural look."]'::jsonb, '["Freecut technology—field-cuttable to any length", "Uniform light output with no pixelation", "Translucent trim conceals minor installation imperfections"]'::jsonb, '["Vertical side-panel lighting"]'::jsonb, '[{"title": "Choose a compatible driver + control", "body": "Select an AMBLUX driver sized to your total connected wattage, plus one wired or wireless control method."}]'::jsonb, '["AMB-EXT-1M", "AMB-EXT-2M", "AMB-Y-EXT", "AMB-2M-6PRTDS", "AMB-HRW-CBLKT", "AMB-FRNT-SWITCH"]'::jsonb, '[{"key": "cct", "label": "Colour temperature"}]'::jsonb, 'silicone-4x8.5-trim', 'AMB-FCST-RC0485TR-24V-30-24-90-3M-18W');
insert into public.amblux_product_pages (slug, category, eyebrow, name, marketing_paragraphs, features, applications, required_accessories, optional_accessory_codes, variant_axes, linear_family_id, default_sku) values ('rigid-10x15', 'linear', 'Rigid linear', 'Freecut Rigid Recess Solder-Free Linear Solution 10 mm x 15 mm', '["Designed for professionals who demand flexibility, performance, and simplicity, our Free-Cut Recessed Linear LED Bar delivers the perfect fit for virtually any installation. Unlike traditional LED strips that can only be cut at fixed intervals, this innovative rigid linear solution can be cut anywhere along its length, allowing for precise customization on-site and eliminating wasted material.", "Engineered specifically for under-cabinet, closet, drawer, shelving, display, and custom millwork applications, it provides a clean, seamless recessed appearance with uniform, high-quality illumination. Its robust construction offers the stability of a rigid linear fixture while maintaining the versatility typically associated with LED tape.", "A complete range of accessories including tape-to-tape connectors, jumper cables, power feeds, and low-profile interconnection cables allows installers to easily navigate corners, bridge gaps, and create continuous lighting layouts with minimal effort. The quick-connect system ensures fast, secure, and reliable electrical connections while making future maintenance or replacement simple and hassle-free. Delivering 12W/m (4W/ft) of efficient, consistent illumination, this system combines exceptional performance with unmatched installation flexibility."]'::jsonb, '["Cut anywhere for a perfect custom fit on every project", "Rigid linear construction for a premium, professional installation", "Complete accessory ecosystem for straight runs, corners, and custom layouts", "Quick, stable connections for faster installation and easy replacement", "Ideal for under-cabinet, closet, drawer, shelving, and millwork applications", "Uniform, dot-free illumination with excellent energy efficiency", "Reduced inventory requirements with one solution for countless applications"]'::jsonb, '["Under-cabinet lighting", "Shelf lighting", "Vertical side-panel lighting", "Toe-kick lighting", "Ambient lighting"]'::jsonb, '[{"title": "Required for a complete run", "items": ["AMB-FCRGL-RC1015TR-PC-1.5M — power cord", "AMB-FCRGL-RC1015TR -90DEG-CON — 90° connector", "AMB-FCRGL-RC1015TR -N2N-CON — end-to-end connector", "AMB-FCRGL-RC1015TR -BRKT — installation bracket (optional per run)"]}, {"title": "Choose a compatible driver + control", "body": "Select an AMBLUX driver sized to your total connected wattage, plus one wired or wireless control method."}]'::jsonb, '["AMB-EXT-1M", "AMB-EXT-2M", "AMB-Y-EXT", "AMB-2M-6PRTDS", "AMB-HRW-CBLKT", "AMB-FRNT-SWITCH"]'::jsonb, '[{"key": "cct", "label": "Colour temperature"}]'::jsonb, 'rigid-10x15', 'AMB-FCRGL-RC1015TR-24V-30-24-90-2.4M-28.8W');
insert into public.amblux_product_pages (slug, category, eyebrow, name, marketing_paragraphs, features, applications, required_accessories, optional_accessory_codes, variant_axes, linear_family_id, default_sku) values ('rigid-6x8', 'linear', 'Rigid linear', 'Freecut Rigid Recess Solder-Free Linear Solution 6 mm x 8 mm', '["Designed specifically for closet, wardrobe, pantry, and storage applications, our Recessed Linear LED Bar delivers elegant, uniform illumination exactly where it is needed. Engineered with a carefully optimized wattage output, this fixture provides the perfect balance between visibility and ambiance, creating a welcoming lighting experience every time a door is opened or a space is entered.", "Its ultra-slim recessed profile integrates seamlessly into shelving, panels, and millwork, remaining virtually invisible until illuminated. Designed for horizontal installation, the fixture distributes light evenly across shelves, hanging areas, and storage spaces, eliminating shadows and dark spots while improving visibility and organization.", "A dedicated quick-connect system allows for fast, secure installation and effortless replacement when required, ideal for luxury closets, walk-in wardrobes, pantries, linen storage, mudrooms, and custom millwork applications."]'::jsonb, '["Optimized light output specifically designed for closets and pantry applications", "Creates a warm, welcoming lighting effect when doors are opened or spaces are entered", "Ultra-slim recessed design for a clean, seamless architectural appearance", "Uniform, dot-free illumination with excellent shelf-to-shelf visibility", "Horizontal installation provides consistent lighting across the entire storage area", "Quick-connect system for fast installation and simple fixture replacement"]'::jsonb, '["Vertical side-panel lighting"]'::jsonb, '[{"title": "Required for a complete run", "items": ["AMB-FCRGL-RC0608TR-PC-1.5M — power cord"]}, {"title": "Choose a compatible driver + control", "body": "Select an AMBLUX driver sized to your total connected wattage, plus one wired or wireless control method."}]'::jsonb, '["AMB-EXT-1M", "AMB-EXT-2M", "AMB-Y-EXT", "AMB-2M-6PRTDS", "AMB-HRW-CBLKT", "AMB-FRNT-SWITCH"]'::jsonb, '[{"key": "cct", "label": "Colour temperature"}]'::jsonb, 'rigid-6x8', 'AMB-FCRGL-RC0608TR-24V-30-24-90-2.4M-18W');
insert into public.amblux_product_pages (slug, category, eyebrow, name, marketing_paragraphs, features, applications, required_accessories, optional_accessory_codes, variant_axes, linear_family_id, default_sku) values ('silicone-10x10-45deg', 'linear', 'Silicone linear', 'Freecut Recess Silicone LED Tape 10 mm x 10 mm 45°', '["Introducing our innovative 45° surface-mounted flexible linear LED solution, engineered with advanced silicone LED technology to deliver seamless, uniform light diffusion in a sleek, minimalist profile. Designed to create a stunning dotless lighting effect without the bulk of traditional diffusers or lenses, this series combines high-end aesthetics with exceptional performance.", "Featuring a premium high-bond 3M® adhesive backing, installation is fast and effortless—whether mounted in grooves or directly onto flat surfaces. For additional rigidity and long-term stability, the fixture can also be secured using mounting clips.", "Available in multiple lengths and pre-wired with power leads on both ends for simplified integration, this versatile solution is ideal for under-cabinet, closet, furniture, and architectural lighting applications where clean lines and ambient illumination are essential."]'::jsonb, '["Surface-mounted installation", "Freecut technology—field-cuttable to any length", "Uniform light output with no pixelation"]'::jsonb, '["Under-cabinet lighting", "Shelf lighting", "Vertical side-panel lighting", "Toe-kick lighting", "Ambient lighting"]'::jsonb, '[{"title": "Required for a complete run", "items": ["AMB-FCST-SR1010-45DEG -CLIPS — mounting clips, bag of 10"]}, {"title": "Choose a compatible driver + control", "body": "Select an AMBLUX driver sized to your total connected wattage, plus one wired or wireless control method."}]'::jsonb, '["AMB-EXT-1M", "AMB-EXT-2M", "AMB-Y-EXT", "AMB-2M-6PRTDS", "AMB-HRW-CBLKT", "AMB-FRNT-SWITCH"]'::jsonb, '[{"key": "cct", "label": "Colour temperature"}, {"key": "length", "label": "Length"}]'::jsonb, 'silicone-10x10-45deg', 'AMB-FCST-SR1010-45DEG -24V-30-24-90-3M-27W');
insert into public.amblux_product_pages (slug, category, eyebrow, name, marketing_paragraphs, features, applications, required_accessories, optional_accessory_codes, variant_axes, linear_family_id, default_sku) values ('rigid-45deg-surface', 'linear', 'Rigid linear', 'Freecut Rigid 45° Surface-Mounted Solder-Free LED Linear Solution', '["Designed specifically for under-cabinet and task lighting applications, our Free-Cut 45° Surface-Mounted Linear LED Bar delivers the perfect balance of performance, aesthetics, and installation flexibility. Featuring an integrated 45° angled profile, it directs light exactly where it''s needed, onto countertops, workspaces, shelving, and display areas, while minimizing glare and improving visual comfort.", "Unlike traditional linear fixtures, this innovative rigid LED bar can be cut anywhere along its length, allowing for a precise custom fit on every project. Whether installed in kitchens, closets, pantries, furniture, or retail displays, it provides seamless, dot-free illumination and a clean architectural appearance.", "The low-profile design mounts easily to any surface using mounting clips for added rigidity and long-term stability. Pre-wired power connections and low-profile interconnection cables make installation fast, clean, and reliable while simplifying future servicing and replacement."]'::jsonb, '["Integrated 45° angle directs light onto work surfaces for optimal illumination", "Cut anywhere for a perfect custom fit with minimal waste", "Dot-free, uniform light output for a premium architectural appearance", "Surface-mounted design eliminates the need for routing or machining", "High-strength 3M® adhesive and optional mounting clips for secure installation", "Quick, stable connections for faster installation and easy maintenance"]'::jsonb, '["Under-cabinet lighting", "Shelf lighting", "Vertical side-panel lighting", "Toe-kick lighting", "Ambient lighting"]'::jsonb, '[{"title": "Required for a complete run", "items": ["AMB-FCRGL-SM-45DEG-PC-1.5M — power cord", "AMB-FCRGL-SM-45DEG -N2N Cbl 15MM — end-to-end cable", "AMB-FCRGL-SM-45DEG -BRKT — installation bracket"]}, {"title": "Choose a compatible driver + control", "body": "Select an AMBLUX driver sized to your total connected wattage, plus one wired or wireless control method."}]'::jsonb, '["AMB-EXT-1M", "AMB-EXT-2M", "AMB-Y-EXT", "AMB-2M-6PRTDS", "AMB-HRW-CBLKT", "AMB-FRNT-SWITCH"]'::jsonb, '[]'::jsonb, 'rigid-45deg-surface', 'AMB-FCRGL-SM-45DEG -24V-30-24-90-2.4M-28.8W');
insert into public.amblux_product_pages (slug, category, eyebrow, name, marketing_paragraphs, features, applications, required_accessories, optional_accessory_codes, variant_axes, linear_family_id, default_sku) values ('rigid-16x10-surface', 'linear', 'Rigid linear', 'Freecut Rigid Surface-Mounted Solder-Free Linear Solution 16 mm x 10 mm', '["Combining the flexibility of LED tape with the durability and premium appearance of a rigid linear fixture, our Free-Cut Surface-Mounted Linear LED Bar is designed to deliver flawless lighting in applications where recessed installation is not possible or desired.", "Engineered for maximum versatility, this innovative solution can be cut anywhere along its length, allowing installers to create the exact fixture length required for every project without waste or compromise. Perfect for under-cabinet lighting, closets, pantries, shelving, display cases, furniture, and architectural millwork.", "A complete range of accessories—including 90° connectors, tape-to-tape connectors, jumper cables, mounting clips, power feeds, and low-profile interconnection cables—allows for fast and flexible installations, whether creating straight runs, navigating corners, or connecting multiple fixtures."]'::jsonb, '["Cut anywhere for a precise, custom fit on every installation", "Surface-mounted design eliminates the need for routing or machining", "Complete accessory ecosystem for corners, extensions, and custom layouts", "Quick, stable connections for faster installation and easy servicing", "Uniform, dot-free illumination with a premium architectural appearance", "Reduced inventory requirements with one solution for multiple applications"]'::jsonb, '["Under-cabinet lighting", "Shelf lighting", "Vertical side-panel lighting", "Toe-kick lighting", "Ambient lighting"]'::jsonb, '[{"title": "Required for a complete run", "items": ["AMB-FCRGL-SM1610-PC-1.5M — power cord", "AMB-FCRGL-SM1610-N2N Cbl 15MM — end-to-end cable", "AMB-FCRGL-SM1610 -N2N-CON — end-to-end connector", "AMB-FCRGL-SM1610 -BRKT — installation bracket"]}, {"title": "Choose a compatible driver + control", "body": "Select an AMBLUX driver sized to your total connected wattage, plus one wired or wireless control method."}]'::jsonb, '["AMB-EXT-1M", "AMB-EXT-2M", "AMB-Y-EXT", "AMB-2M-6PRTDS", "AMB-HRW-CBLKT", "AMB-FRNT-SWITCH"]'::jsonb, '[{"key": "cct", "label": "Colour temperature"}]'::jsonb, 'rigid-16x10-surface', 'AMB-FCRGL-SM1610-24V-30-24-90-2.4M-28.8W');
insert into public.amblux_product_pages (slug, category, eyebrow, name, marketing_paragraphs, features, applications, required_accessories, optional_accessory_codes, variant_axes, linear_family_id, default_sku) values ('recessed-puck', 'puck', 'Puck lights', 'The Poly — Recessed Puck Light', '["Introducing our most versatile puck light series, designed for maximum convenience and style. These lights are easy to install thanks to their quick connection to the body of the puck lights, a slim profile and a removable cover plate. Made with a high-quality aluminum heat sink, they ensure durability and efficiency.", "All fixtures have a switch to allow for three appealing colour temperatures: warm white (3000K), neutral white (4000K), or cool white (5000K). Transform your space effortlessly with our innovative puck lights!"]'::jsonb, '["Integrated selectable switch — 3000 K / 4000 K / 5000 K", "Quick-connect to the body of the light using a 1500 mm power cable", "Powerful LED light engine with a removable finish plate design"]'::jsonb, '["Under-cabinet lighting", "Shelf lighting", "Ambient lighting"]'::jsonb, '[{"title": "Choose a faceplate finish", "items": ["AMB-PK-RC58-FACEPLATE-WH — White", "AMB-PK-RC58-FACEPLATE-SN — Satin Nickel", "AMB-PK-RC58-FACEPLATE-BK — Black"]}]'::jsonb, '["AMB-EXT-1M", "AMB-EXT-2M", "AMB-Y-EXT", "AMB-2M-6PRTDS", "AMB-HRW-CBLKT", "AMB-FRNT-SWITCH"]'::jsonb, '[]'::jsonb, null, 'AMB-PK-RC58-24V-345-90-35W-LE');
insert into public.amblux_product_pages (slug, category, eyebrow, name, marketing_paragraphs, features, applications, required_accessories, optional_accessory_codes, variant_axes, linear_family_id, default_sku) values ('surface-puck', 'puck', 'Puck lights', 'Slim Surface Puck Light', '["Introducing our versatile puck light series, crafted for both convenience and style. With a sleek design and magnetic cover plate, these lights are easy to install in either a surface mount or recessed configuration. Constructed from high-quality aluminum, they provide both durability and efficiency.", "Each fixture features a convenient switch that allows you to choose from three inviting color temperatures: warm white (3000K), neutral white (4000K), or cool white (5000K). Transform your space effortlessly with our innovative puck lights!"]'::jsonb, '["Integrated selectable switch — 3000 K / 4000 K / 5000 K", "Ultra-slim design for a recessed appearance with the ease of surface-mount installation", "Soft, uniform lighting output"]'::jsonb, '["Under-cabinet lighting", "Shelf lighting", "Ambient lighting"]'::jsonb, '[{"title": "Choose a compatible driver + control", "body": "Select an AMBLUX driver sized to your total connected wattage, plus one wired or wireless control method."}]'::jsonb, '["AMB-EXT-1M", "AMB-EXT-2M", "AMB-Y-EXT", "AMB-2M-6PRTDS", "AMB-HRW-CBLKT", "AMB-FRNT-SWITCH"]'::jsonb, '[{"key": "finish", "label": "Finish"}]'::jsonb, null, 'AMB-PK-SLSR35-24V-345-90-2W-WH');
insert into public.amblux_product_pages (slug, category, eyebrow, name, marketing_paragraphs, features, applications, required_accessories, optional_accessory_codes, variant_axes, linear_family_id, default_sku) values ('central-control-driver', 'driver', 'Drivers', 'Central Control Driver Series', '["At the heart of the AMBLUX lighting ecosystem is our Central Control Driver Series, engineered to simplify installation, reduce complexity, and provide unmatched flexibility for residential and commercial lighting projects. Available in 24W, 36W, 60W, and 96W versions, these cULus-certified drivers serve as the central hub for all lighting, dimming, and sensor controls throughout an installation.", "Designed specifically for the North American market, each driver features integrated plug-and-play connectivity and dual control outputs, allowing lighting fixtures, sensors, and controls to be connected quickly and securely without complicated wiring. Compatible with a wide range of wired and wireless controls—including door sensors, motion sensors, touch dimmers, touch on/off switches, hand-wave sensors, and wireless wall controls—the series eliminates the need for multiple control platforms.", "For larger projects, the system offers a unique driver-linking capability, allowing multiple drivers to communicate and operate from a single control point—enabling larger installations to function as one cohesive system while keeping the simplicity of a plug-and-play solution."]'::jsonb, '["Centralized control platform — one driver manages lighting, sensors, dimming, and switching", "Plug-and-play installation — quick-connect ports reduce wiring time", "Universal sensor compatibility — door switches, motion sensors, touch dimmers, hand-wave sensors, wireless controls", "Dual control outputs — dedicated ports for dimming and accessory controls", "Driver-to-driver communication — link multiple drivers to one sensor or switch", "Scalable system design — from a single cabinet to large commercial projects", "cULus certified — fully compliant for North American installations"]'::jsonb, '[]'::jsonb, '[{"title": "Choose a compatible control", "body": "Pick one or more wired or wireless controls to pair with this driver — see Compatible controls in the specifications below."}]'::jsonb, '["AMB-EXT-1M", "AMB-EXT-2M", "AMB-Y-EXT", "AMB-2M-6PRTDS", "AMB-HRW-CBLKT", "AMB-FRNT-SWITCH"]'::jsonb, '[{"key": "wattage", "label": "Wattage"}]'::jsonb, null, 'AMB-DRV-24V-24W');
insert into public.amblux_product_pages (slug, category, eyebrow, name, marketing_paragraphs, features, applications, required_accessories, optional_accessory_codes, variant_axes, linear_family_id, default_sku) values ('wired-sensor-controls', 'control', 'Controls', 'Wired Sensor Switches', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"title": "Requires", "body": "One of the AMBLUX Central Control drivers (24W / 36W / 60W / 96W), sized to your connected wattage."}]'::jsonb, '["AMB-EXT-1M", "AMB-EXT-2M", "AMB-Y-EXT", "AMB-2M-6PRTDS", "AMB-HRW-CBLKT"]'::jsonb, '[{"key": "type", "label": "Control type"}]'::jsonb, null, 'AMB-WR-SS-TOUCH-DMR');
insert into public.amblux_product_pages (slug, category, eyebrow, name, marketing_paragraphs, features, applications, required_accessories, optional_accessory_codes, variant_axes, linear_family_id, default_sku) values ('wireless-sensor-controls', 'control', 'Controls', 'Wireless Sensor Switches', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"title": "Requires", "body": "One of the AMBLUX Central Control drivers (24W / 36W / 60W / 96W), sized to your connected wattage. Switch models also require the AMB-WRLSS-SS-RCVR receiver."}]'::jsonb, '["AMB-EXT-1M", "AMB-EXT-2M", "AMB-Y-EXT", "AMB-2M-6PRTDS", "AMB-HRW-CBLKT"]'::jsonb, '[{"key": "type", "label": "Control type"}]'::jsonb, null, 'AMB-WRLSS-SS-RCVR');
insert into public.amblux_product_pages (slug, category, eyebrow, name, marketing_paragraphs, features, applications, required_accessories, optional_accessory_codes, variant_axes, linear_family_id, default_sku) values ('wireless-dimming-controls', 'control', 'Controls', 'Wireless Dimming — Kinetic RF & Bluetooth App', '["Bluetooth controller for 4-channel output plus 1 sensor channel, with a single-color soft on/off function. Plug and play, 12–24 VDC, max 4A per channel, 4 channels of 48–96W output, over a 2.4G mesh Bluetooth network."]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"title": "Requires", "body": "One of the AMBLUX Central Control drivers (24W / 36W / 60W / 96W), sized to your connected wattage. Kinetic RF switches and the Bluetooth App also require the AMB-DMG-WRLSS-RCVR receiver."}]'::jsonb, '["AMB-EXT-1M", "AMB-EXT-2M", "AMB-Y-EXT", "AMB-2M-6PRTDS", "AMB-HRW-CBLKT"]'::jsonb, '[{"key": "type", "label": "Control type"}]'::jsonb, null, 'AMB-DMG-WRLSS-RCVR');

-- Backfill hero image from each page's default SKU.
update public.amblux_product_pages pp set hero_image_url = p.image_url
